        c.globalAlpha = Math.max(0, Math.min(1, isNum(alpha) ? alpha : 1));
        c.translate(px, py);
        if (rot) c.rotate(-rot);
        c.font = Math.max(1, fs) + 'px Rubik,"Segoe UI",system-ui,sans-serif';
        c.textAlign = 'left'; c.textBaseline = 'middle';
        c.fillStyle = str(o.attrs.get('color') || '#FFFFFF');
